/* Add newest releases first: version, date, short concrete changes. */
const mealReleases=[{"version": "34.13", "date": "2026-11-25", "time": "03:10", "author": "Claude", "changes": ["Журнал за неделю, месяц или свой период показывает, за какие дни, — «18–24 ноября» вместо «Среднее значение».", "Даты и время везде одинаково: «24 ноября, 09:05», год — только если не текущий. Фастинг — словами: «14 ч 5 мин».", "Счётчик убирается смахиванием влево, корзины в листе больше нет. У выключателя фастинга одна ручка.", "В чате уголок облачка у своей стороны почти острый.", "Без входа над микрофоном — полоска «Войди», как в Day.", "Нижние листы открываются одинаково плавно во всех приложениях, ручка сверху крупнее, заголовок листа жирнее, подзаголовок ближе к заголовку.", "Кнопки внутри приложения — одного размера; кнопки «Войти» и «Отмена» на экране входа остались крупнее, подзаголовок «Войди в аккаунт» — ярче.", "Полоска браузера и строка времени на iPhone окрашены в цвет приложения и темы."]},
 {"version": "34.12", "date": "2026-11-25", "time": "01:05", "author": "Claude", "changes": ["Замеры тела словами: «талия 82, грудь 100», «вчера бёдра 98, вес 79,5» — бот записывает в общие «Замеры тела». «Бицепс 35» спросит сторону, «бедро 98» — замер это или еда. «Какая у меня талия» — последний и прошлый замер.", "Повтор и перенос: «повтори вчерашний ужин», «на ужин как вчера», «скопируй вчерашний день», «перенеси кашу на вчера», «нет, это было вчера». «Верни овсянку» возвращает удалённое в этом разговоре.", "Счётчики голосом: «ещё чашку кофе по счётчику», «мои счётчики». Свой продукт: «поменяй калории у сырников на 220», «удали мой продукт сырники». Рецепт одной фразой: «сохрани рецепт омлет: яйцо 2, молоко 100 мл».", "Свои меры и настройки одной фразой: «моя кружка 350 мл», «поставь 1800 калорий», «белка 120 г в день», «перекус меньше 200 ккал», «обед с часу до пяти», «фастинг 16 на 8 с 8 вечера». Час без «утра» или «вечера» бот берёт ближе к приёму: «ужин на 7» — 19:00.", "Напитка нет в базе (компот из фейхоа, узвар, иван-чай) — бот честно говорит «в базе нет» и предлагает похожие кнопками. Просто «компот» — спросит какой. Солёных помидоров в базе нет — так и скажет. «Компот старка» — это стакан.", "«Домашние блюда» 1.1: в супе с фрикадельками 50 г фрикаделек на тарелку (было 30 г), железо — «нет данных»."]},
 {"version": "34.11", "date": "2026-11-24", "time": "16:50", "author": "Claude", "changes": ["Фасоль: бот знает, как варить каждый вид — красную (кидни), белую, чёрную, пинто, лиму: замочить, воду слить, первые 30 минут сильно кипятить. «Можно ли есть сырую фасоль» — ответ, как сделать её безопасной. «Кинди» бот понимает как «кидни».", "«Какао вместо шоколада» — как сделать: масло, какао и сахар по вкусу, и ссылка на рецепт. «Какао вместо шоколада в брауни» бот понимает и без вопроса.", "Витамин B3 — две строки: «ниацин» и «ниациновый эквивалент». Разные базы дают разное, теперь они не смешиваются.", "Йод в молоке 1,5 % по немецкой базе — 9,5 мкг вместо 2,8 (исправление самой базы).", "Пирожки в «Домашних блюдах» пересчитаны по начинкам: с капустой — 184 ккал печёный и 192 жареный.", "Где у продукта в составе блюда нет данных о веществе, у блюда тоже «нет данных», а не ноль."]},
 {"version": "34.10", "date": "2026-11-24", "time": "05:40", "author": "Claude", "changes": ["Бот знает больше о готовке: варка (бульоны, курица, говядина, язык, креветки, кальмары, кукуруза), жарка, запекание, соленья и засол, варенье, кремы, шоколад, бакалея. Бобовые — по видам: красная, чёрная, белая фасоль, горох, маш, соя и другие.", "Бот подсказывает замены: «чем заменить муку в сырниках», «что можно вместо майонеза».", "Советы по питанию: «можно ли есть сладкое на ночь», «сколько воды в день». Под каждым — предупреждение: польза и вред у всех разные, при болезни лучше спросить врача.", "«Масло загорелось» — бот сразу говорит, что делать, даже без вопроса.", "«Гречка или рис» — бот не пишет оба, а спрашивает, что из двух.", "Одна еда на стыке завтрака и обеда остаётся в одном приёме."]},
 {"version": "34.9", "date": "2026-11-24", "time": "05:10", "author": "Claude", "changes": ["Meal передаёт в Day время своих периодов — Завтрак, Обед, Ужин. Day показывает их на шкале времени в «Разделах главного экрана»."]},
 {"version": "34.8", "date": "2026-11-23", "time": "22:07", "author": "Codex", "changes": ["Во время ожидания входа смайлик остаётся того же размера и на том же месте, что и на приветственном экране."]},
 {"version": "34.7", "date": "2026-11-23", "time": "21:40", "author": "Claude", "changes": ["Новые темы: «Малахит» — приглушённый зелёный, как «Бордо» по тону, и «Спокойный синий» — глубокий синий. Обе стоят сразу после «Бордо».", "Новая тема «Ягодное небо»: от малиновой розы в углу к ясному синему.", "«Орхидея» спокойнее: правый верхний угол больше не пересвечен, главная кнопка цвета сливы. Тема «Аметист» убрана. Если она была выбрана, сама включится «Орхидея».", "Новый порядок тем: Мята, Фиолетовый бриз, Бордо, Малахит, Спокойный синий, Орхидея, Ягодное небо, Золотой закат, затем ночные.", "Кольцо энергии в цвет темы: у «Мяты» — «Отмель», у «Малахита» — «Изумруд», у «Спокойного синего» — «Морозное утро», у «Орхидеи» — «Фуксия», у «Золотого заката» — «Перламутр»."]},
 {"version":"34.6","date":"2026-11-23","time":"20:23","author":"Codex","changes":["В профиле над «Удалить аккаунт» появилась политика конфиденциальности. При регистрации по паролю нужно отметить согласие с ней."]},
 {"version": "34.5", "date": "2026-11-23", "time": "19:55", "author": "Claude", "changes": ["На первом экране под «Уже есть аккаунт? Войти» — строка «Тестовая версия: покупки бесплатные, деньги не списываются».", "«Познакомиться с …» теперь называется «Заглянуть в Meal без аккаунта» и стала яркой, как «Войти»."]},
 {"version": "34.4", "date": "2026-11-23", "time": "17:11", "author": "Claude", "changes": ["Бот знает кулинарные приёмы: «когда солить рис», «солить картошку при жарке в начале или в конце», «почему картошка тушится, а не жарится», «когда добавлять чеснок», «нужно ли промывать рис», «яйца в холодную или кипящую воду», соль в макаронах, грибах, луке, мясе и фасоли, отдых мяса после жарки. Под ответом — откуда это взято; где источники спорят, бот называет обе версии.", "Приёма, которого ещё нет («когда солить суп»), бот честно не знает и записывает вопрос, чтобы добавить.", "После «свадебного супа» «бульон с фрикадельками» бот пишет сразу бульоном из «Домашних блюд», а не предлагает записать по частям."]},
 {"version": "34.3", "date": "2026-11-23", "time": "17:10", "author": "Claude", "changes": ["Зелёная тема теперь одна — «Мята»: бирюза, отмель и тёплый песок, как лагуна в полдень.", "Тема «Лагуна» убрана. Если она была выбрана, сама включится новая «Мята»."]},
 {"version": "34.2", "date": "2026-11-23", "time": "16:40", "author": "Claude", "changes": ["Кольцо энергии рисуется по-новому: на конце дуги больше нет заметной точки, цвет переходит ровно до самого края.", "У тем «Бордо», «Ночная бухта», «Полуночный ирис» и «Неоновая ночь» кольцо и полоски белков, жиров, углеводов и клетчатки теперь в цветах темы. В остальных темах цвета прежние."]},
 {"version": "34.1", "date": "2026-11-23", "time": "06:10", "author": "Claude", "changes": ["Свою добавку можно завести в чате: «заведи свою добавку Магний B6». Бот спросит форму и состав («магний 100 мг, витамин B6 5 мг») и сохранит её в «Мои добавки», а потом предложит записать приём.", "Новый каталог «Домашние блюда» в «Кухнях мира»: суп с мясными и рыбными фрикадельками, свадебный суп, бульон с фрикадельками, пирожки печёные и жареные — с капустой, картошкой, печенью, картошкой и печенью. «Суп с фрикадельками» бот пишет тарелкой 300 г, «пирожок с капустой» — штукой 75 г.", "«Пирожок» без начинки — бот спросит, с чем. «Два пирожка» — тоже вопрос.", "Блюдо, которого нет в базе («вареники с вишней»), бот честно пишет «В базе нет» и не подставляет похожее чужое блюдо.", "«Как готовить» знает больше: овсянка, макароны, варёный картофель, брокколи, морковь, свёкла.", "«Рецепт плова», «как приготовить шурпу» — бот показывает рецепт из «Моих рецептов», сборников или узбекской кухни: состав на порцию и ссылку на рецептуру."]},
 {"version": "34", "date": "2026-11-23", "author": "Codex", "changes": ["В Meal можно войти через Google или по почте. При первом входе через Google приложение поможет открыть прежние записи.", "В настройках профиля можно скачать данные и удалить аккаунт. Перед удалением приложение попросит подтвердить выбор.", "В журнале скрыты подсказки об отсутствии сведений о составе продуктов."], "time": "04:31"},
 {"version": "33.37", "date": "2026-11-23", "time": "03:24", "author": "Claude", "changes": ["Цель настраивается в чате: «настрой цели», «хочу похудеть», «рассчитай мою норму». Бот спрашивает по шагам — отвечай кнопкой или словами («метр восемьдесят»), «назад» и «отмена» работают. В итоге — калории, белки, жиры, углеводы и кнопка «Сохранить».", "Свой продукт заводится в чате: «заведи свой продукт» или кнопка «Завести свой продукт» под «В базе нет». Бот спрашивает название и КБЖУ, калории сверяет с белками, жирами и углеводами.", "Бот подсказывает по приложению: «где цели», «как включить фастинг», «куда записать вес», «что ты умеешь» — короткий ответ и кнопка, которая открывает нужный экран.", "«Овсяное молоко» — напиток, а не каша на молоке. «Кефир 2,5 стакан» — кефир 2,5 %.", "Бот советует блюда по кухне и из того, что есть: «посоветуй грузинское», «что приготовить из курицы и риса» — рецепты, где это есть в составе, и чего ещё не хватает.", "Бот подсказывает, как готовить: «как варить гречку», «сколько варить яйцо» — короткие карточки из справочника.", "Короткие команды: «включи фастинг», «добавь в избранное» и другие — бот делает сам; настройка по шагам: цели → приёмы пищи → фастинг → каталоги → счётчик.", "«Сухая колбаса с салом» — сушёная колбаса; после варёной «сухая колбаса» больше не путается."]},
 {"version": "33.36", "date": "2026-11-22", "time": "21:19", "author": "Claude", "changes": ["Бот советует, что приготовить: «что на завтрак», «чем поужинать», «быстрый белковый обед» — три рецепта из подборок и твоих рецептов, с учётом остатка калорий. В дневник совет не идёт.", "Рецепты: неясная строка состава считается по первому варианту, а не нулём.", "Просто «молоко» без процента — теперь 2,5 %. В базе появилось молоко 2,5 %; «молоко 3,5 %» и другие проценты — как сказано.", "Бот отвечает о составе продукта: «сколько сахара в шоколаде», «калорийность гречки», «что в составе сникерса» — из базы, без записи.", "Бот отвечает о цели и остатке: «какая у меня цель», «сколько мне осталось калорий», «моя норма белка».", "Бот считает вещества за день: «сколько клетчатки я съел», «хватает ли мне железа», «чего мне не хватает». Список ненайденного — «чего не хватает в базе».", "БАДы голосом: «омега-3 три капсулы», «две таблетки магния» — приём своей добавки записывается в раздел БАДов.", "Бот: «рис не доел» после «груша и рис» — убавляется только рис; компот из фейхоа больше не пишется сливовым; «стебель» зелёного лука, чеснока, сельдерея; отварная говядина; «макароны сливочном соусе» без «в»; «и час ещё кофе» — кофе в 13:00.", "Бот: «молоко в кофе 50 мл», «одна треть стакана», «полторы тысячи грамм», «стакан и ещё полстакана», «12 яиц», «несколько ложек», омлет из двух яиц, маленькая тарелка, списки без запятых («яблоко огурец помидор»), «рыба с овощами» и «картошка с мясом» — с вопросом, что именно."]},
 {"version": "33.35", "date": "2026-11-22", "time": "18:20", "author": "Claude", "changes": ["Короткое сообщение без плашки снова стоит низко, сразу над кнопкой микрофона.", "Пока идёт фастинг, сообщение стоит над плашкой фастинга и не закрывает её."]},
 {"version": "33.34", "date": "2026-11-22", "time": "17:14", "author": "Claude", "changes": ["Бот: ложка мёда — чайная, 7 г, если не сказано, какая. «Столовая ложка мёда» — 21 г.", "Бот: ложки после «с» — мера добавки, а вес в конце — всего блюда: «творог с двумя ложками мёда 200 г» — 186 г творога и 14 г мёда, «творог со столовой ложкой мёда 200 г» — 179 и 21 г.", "Бот: «творог с двумя ложками сметаны 200 г» — 170 г творога и 30 г сметаны, а не 200 г сметаны."]},
 {"version": "33.33", "date": "2026-11-22", "time": "16:00", "author": "Claude", "changes": ["Все тексты обращаются на «ты», и экраны входа, профиля и целей тоже: «Войди в аккаунт», «Проверь адрес почты», «Не помню пароль».", "Понятнее подсказки: «Каталог этого продукта выключен. Включи его в настройках», «Добавки ещё загружаются. Попробуй через секунду».", "Короткие сообщения на iPhone больше не наезжают на кнопку с микрофоном: висят чуть выше неё."]},
 {"version": "33.32", "date": "2026-11-22", "time": "14:17", "author": "Claude", "changes": ["Бот: блюдо есть в базе — пишется оно, без вопроса. Нет — две записи: «творог с мёдом 200 г» — мёд чайной ложкой, творог — остаток веса. «Борщ без сметаны» — борщ без неё.", "Бот: жирность — часть названия, а не вес: «творог 5 процентов 200 г», «пятипроцентный творог». «Шоколад 70 %» — доля какао, «пиво 4,5 %» — не жирность.", "Бот понимает поправки внутри фразы («ой, 250», «два куска, нет, три», «это не баранина, а говядина») и список без запятых.", "Бот: меры и числа — «ст. л.» с точкой — ложка, «около двухсот» — 200, «грамм пятьдесят сыра» — 50 г, «стопка» — рюмка только у крепкого, стакан орехов — 130 г.", "Бот: крупы и каши без слова — готовые, «гречневая каша» — варёная гречка; хлебец, панкейк, тост, кусок пирога — свой вес; кусок хлеба — ломтик; «блин» в начале фразы — восклицание; «купил батон» — не еда.", "Бот: молочное — больше слов и ошибок речи; «каша на молоке» и «творожный десерт» без вида — вопрос; ряженка, варенец и другие, которых нет в базе, — «нет в базе», а не похожее.", "Бот: сладкое — марки из базы (сникерс, твикс, киткат, нутелла и другие), вес штуки («2 ириски» — 14 г), «полсникерса», «всю плитку».", "Бот: фрукты, овощи, зелень и орехи — вес штуки, ласковые слова, сорта; «кориандр», «кинза» — свежая зелень, сушёная и семена — только если сказано.", "Бот: напитки и мясо — «пиво 0,5» — 500 мл, эспрессо — шот, «какао с молоком» — напиток, а не сухая смесь, «миндальное молоко» — растительный напиток, съеденное мясо и рыба без способа — готовые.", "Бот: просто «плов», «паста», «манты», «хинкали» — как записывал в последний раз, иначе обычное блюдо; «овощной салат» без состава — вопрос."]},

 {"version": "33.31", "date": "2026-11-22", "time": "05:30", "author": "Claude", "changes": ["Бот: любые формы макарон — рожки, фузилли, бантики, ракушки, пенне, перья — это макароны, варёные; «сухие», «сырые», «не готовые» — сухие.", "Бот: просто «рожок» или «рожки» — вопрос: мороженое или макароны. «Рожки с курицей», «сварил рожки» — макароны.", "Бот: мороженое без вкуса — вопрос «какое?», ванильное первым; пломбир и эскимо находятся.", "Бот: перепёлки штуками — готовое мясо; куриная отбивная — жареное филе; свиная — жареная, не в желе; «борщ с говядиной» — сразу борщ.", "Бот: «курочка», «куры» — курица, а не растительная замена; «крабовые палочки» — крабовые, 17 г штука; «рыба жареная» — вопрос «какая?»; «баранина на кости 300» — 300 г мяса.", "Бот понимает больше искажений речи: «ass ball» — асыдзбал, «Lobo» — лобио, «фей Huawei» — фейхоа.", "Бот: новые слова из словаря русской речи о еде — нут, маш, батат, попкорн, чизкейк (запечённый), гречка на воде, тост, спагетти в томатном соусе с весом и другие; «смородина», «дюшес» — вопрос."]},

 {"version": "33.30", "date": "2026-11-22", "time": "04:35", "author": "Claude", "changes": ["«Настроить тему» → «Главная кнопка»: кружки с микрофоном как в Color Studio — настоящий цвет и тень кнопки, белый микрофон.", "Профиль: списка замеров веса больше нет (замеры — в журнале), подписи полей жирнее, «Пол» и единицы — переключатели с отступом внутри контура, подписи по центру.", "Переключатели между вариантами везде одного вида: контур 44, выбранная пилюля 36.", "Выключатели одного вида во всех приложениях, галочки — белый квадрат, листы снизу как в Day, текст в белых кнопках — цвета темы.", "Переключатель каталогов снова ровная пилюля.", "Окно счётчика — в цвет фона.", "В БАДах «Купить» только под картинкой, без подписи «Тестовая покупка»; пилюли магазина — цвета темы.", "Без темы текст в белых кнопках сливовый, как вкладки периода.", "«Золотой закат» с тёмным низом."]},
 {"version": "33.29", "date": "2026-11-21", "time": "21:50", "author": "Claude", "changes": ["Кнопка «Войти» и другие главные кнопки на экранах входа — ровного цвета, без выпуклого блика: в теме — цвет темы, без темы — цвет приложения."]},
 {"version": "33.28", "date": "2026-11-21", "time": "20:40", "author": "Claude", "changes": ["Экран загрузки со смайликом сразу в цвете выбранной темы, без вспышки старого цвета.", "Без темы приложение выглядит как раньше: таблица замеров — в исходных цветах.", "С темой в её цвет окрашиваются листы снизу, «Свой период» и календарь, выключатели.", "Цвет кнопок «Как у темы» берётся с фона темы у самого верха, на уровне шапки, и затемняется, пока белый значок на нём хорошо читается. Ночные темы, «Бордо» и «Фиолетовый бриз» — со своим цветом.", "Одиночные кнопки — во всю ширину и по центру («Добавить счётчик», «Создать свой продукт»).", "Выключатель BLS — в цвет темы.", "Цвета приложения встроены в страницу: при плохой сети текст не становится чёрным, нижняя панель не прозрачная."]},
 {"version": "33.27", "date": "2026-11-21", "time": "14:50", "author": "Claude", "changes": ["Журнал: выбор периода и «Поделиться» — общие с Day и Sport; «Свой период» — лист снизу, как в Sport.", "«По группам / От дефицита» — в стиле Sport.", "Пока открыт лист или окно, страница за размытым фоном не прокручивается пальцем.", "Иконка микрофона — как в Day.", "Центральная кнопка — как в Sport: светлый выпуклый шар цвета приложения с мягкой тенью, без свечения; в любой теме — по тому же правилу из цвета кнопок темы.", "Выбранное в переключателях — жирность 600 и цвет из темы.", "Длинное сообщение внизу переносится на вторую строку, а не обрезается.", "Профиль: пилюли единиц измерения больше не сплющены.", "Экраны аккаунта и настроек — по общим правилам формы: пилюли, поля 12, выключатели 42 × 25, карточки как в приложении.", "Настройки внизу: строка синхронизации по центру, под ней «Выйти»."]}, {"version": "33.26", "date": "2026-11-21", "time": "12:40", "author": "Claude", "changes": ["Единый вид с Day и Sport: карточки скруглены сильнее, кнопки, чипы и фильтры — пилюли, поля и поиск одной высоты, листы снизу и выключатели — как в Day и Sport.", "Подписи нижнего меню, заголовки разделов Настроек и короткое сообщение — как в Day."]}, {"version": "33.25", "date": "2026-11-21", "time": "12:35", "author": "Claude", "changes": ["Цвета приложения собраны в одном общем файле: тема меняет не только фон и главную кнопку, но и текст, подписи, переключатели и выбранную вкладку внизу.", "Таблица замеров — в цвет темы: третья колонка на тон тусклее первой, следующие — тот же цвет под полупрозрачным белым слоем."]}, {"version": "33.24", "date": "2026-11-21", "time": "12:00", "author": "Claude", "changes": ["Размеры и жирность текста — по общей шкале Happy, как в Day и Sport: мелкие подписи стали 12, промежуточные размеры выровнены.", "Магазин: «31 шаблон» и цена на карточке — в одну строку."]}, {"version": "33.23", "date": "2026-11-21", "time": "05:25", "author": "Claude", "changes": ["Замеры тела: «+ Замер» поднимает таблицу к верху экрана — раньше она оставалась внизу за краем."]}, {"version": "33.22", "date": "2026-11-21", "time": "05:12", "author": "Claude", "changes": ["«Настроить тему» — как в Sport: Настройки → «Настроить тему», последняя строка в карточке аккаунта. Две ленты — «Тема» и «Главная кнопка»; нажал — сразу применяется и сохраняется. Прежнее «Выбрать оформление» убрано.", "Журнал → «Замеры тела»: полосы таблицы — в цвет темы."]},
 {"version": "33.21", "date": "2026-11-21", "time": "03:45", "author": "Claude", "changes": ["Фастинг по дням недели: в «Настроить приёмы пищи» под шкалой фастинга — кружки Пн … Вс. Отмеченный день — день, когда фастинг начинается; по умолчанию отмечен сегодняшний.", "Пока фастинг идёт, над нижним меню — фиолетовая плашка: «Фастинг до 12:00», обратный отсчёт и «Отменить». После «Отменить» — сообщение «Фастинг отменён · Вернуть».", "Записал еду во время фастинга — «Фастинг прерван · Отменить запись». Фастинг в настройках остаётся включённым и в следующий отмеченный день начнётся сам.", "Под кольцом — итог дня: «Фастинг выдержан» или «Фастинг прерван». Дошёл до конца без еды — «Поздравляю! Фастинг закончен успешно».", "«Сборники» → Магазин: новая карточка «Кавказская кухня» — 103 блюда, страница как у узбекской кухни.", "Национальные базы BLS, USDA, MEXT и KFCT в магазине — без цены и «Купить»: они входят в Meal и включаются в «Настройки → Каталоги». Подписи баз уточнены: KFCT — 2026 год, у BLS — полное название, DOI и лицензия CC BY 4.0.", "Строки продукта в дневнике и в «Что съел»: вместо стрелок — лупа, корзина при свайпе — по центру строки. Синие сообщения — сразу над кнопкой микрофона, без прозрачности; после сохранения настроек — «Настройки сохранены»."]},
 {"version": "33.20", "date": "2026-11-20", "time": "14:35", "author": "Claude", "changes": ["Карточка продукта: убран шов под закреплённой шапкой. Шапка залита тем же переходом цвета, что и фон."]},
 {"version": "33.19", "date": "2026-11-20", "time": "14:10", "author": "Claude", "changes": ["Диалог «Что съел» — новый, по макету Михалыча и Астамура: в одном сообщении видно, что бот записал, и строки с вопросами.", "Строку правят на месте: короткое нажатие — порция, долгое — карточка продукта, свайп влево — удалить, «＋ Добавить» — ещё один продукт. «Отменить» убирает записанное и возвращает фразу в поле ввода. Для замены — похожие продукты и поиск по включённым каталогам.", "Приём пищи — кнопками вверху диалога. Пока кнопку не трогал, приём выбирает бот; нажал — пишет туда, пока диалог открыт.", "Общее слово бот уточняет сначала по избранному: в избранном сулугуни — «сыр» запишется как сулугуни. В карточке продукта появилась звёздочка «В избранное».", "Запись еды прежняя: проверочные фразы записываются так же, как в 33.18."]},
 {"version": "33.18", "date": "2026-11-20", "time": "12:57", "author": "Claude", "changes": ["Замеры: и новый замер, и правка — прямо в таблице, без отдельного листа. Карандаш у даты открывает правку в том же столбце, корзина под столбцом удаляет замер.", "В углу таблицы сначала «Отмена», после ввода — «Сохранить». Вписанное сохраняется и само, когда выходишь из поля.", "Шапка с датами закреплена, история листается вбок полосатыми столбцами по одному. Выбор периода сравнения — над силуэтом."]}, {"version": "33.17", "date": "2026-11-19", "time": "12:20", "author": "Claude", "changes": ["Новый экран «Настроить приёмы пищи» — третья строка в настройках. У каждого приёма своё время на шкале суток: перекус 00:00–05:00, завтрак 05:00–13:00, обед 13:00–18:00, ужин 18:00–24:00. Периоды идут подряд: двигаешь конец одного — сдвигается начало соседнего. Нажатие на время — точный выбор колёсами.", "«Редактировать»: завтрак, обед, ужин и перекус с замком — их не переименовать, не удалить и не перенести. Свои приёмы и перекусы, в том числе ночной, — через «Добавить приём»: переносятся за три черты, удаляются свайпом влево, есть «Вернуть».", "Фастинг — отдельная белая полоса с выключателем, может идти через полночь. Пока это только настройка: запись еды он не останавливает.", "Бот записывает еду по этим периодам: первая еда в периоде — основной приём, до 20 минут после прошлой записи — продолжение, меньше 150 ккал и больше 20 минут — перекус. Пороги меняются в «Правилах перекуса», там же можно проверить на примере.", "Счётчики и запись руками тоже берут приём по периодам: до 24:00 — ужин, пока не подвинешь границу. Прежний список «Разделы» из настроек убран."]},
 {"version": "33.16", "date": "2026-11-19", "time": "03:52", "author": "Claude", "changes": ["Нижнее меню видно поверх профиля и целей; нажал вкладку меню — лист закрылся и открылась вкладка.", "Замеры: новый замер вписывается прямо в таблицу. «+ Замер» — в углу таблицы; нажал — столбцы уезжают вправо, в белом столбце подчёркнутые поля и сегодняшняя дата. «Отмена» в углу, «Сохранить замер» под таблицей."]}, {"version": "33.15", "date": "2026-11-19", "time": "03:05", "author": "Claude", "changes": ["Для разработчика: выключатель «Диктовки с шортката „Еда“». Только для владельца шортката, у всех выключен. Включён — Meal сам забирает сказанное в шорткат, бот записывает это временем диктовки, а о непонятном спрашивает в «Что съел»."]}, {"version": "33.14", "date": "2026-11-19", "time": "01:57", "author": "Claude", "changes": ["Цель веса — одна на профиль: поменял в Meal или Sport — поменялась везде. Силуэт замеров во всех трёх приложениях красит разницу по этой цели (при наборе прибавка бирюзовая, при снижении — розовая).", "Пустые замеры: простой текст и под ним «+ Замер»."]}, {"version": "33.13", "date": "2026-11-19", "time": "01:41", "author": "Claude", "changes": ["«Гречка с грибами, всего 200 г» — 200 г на всё блюдо: части в сумме дают ровно названный вес.", "«Грушу съел, а рис не ел» — рис в дневник не идёт. Так же «не стал», «не трогал», «не пил»."]}, {"version": "33.12.1", "date": "2026-11-19", "time": "01:06", "author": "Claude", "changes": ["Бот понимает «грам» с одной «м», «килограм» и «милилитр»: «140 грам квашеной капусты» записывается как 140 г капусты."]}, {"version": "33.12", "date": "2026-11-18", "time": "23:59", "author": "Claude", "changes": ["Бот записи еды включён у всех: скажи или напиши, что съел, — понятное он запишет сам, о неясном спросит. Выключатель — в «Для разработчика».", "Бот выучил живую речь на 107 настоящих диктовках: «квашеная капуста» — капуста, а не её сок; «лук» — репчатый; «чёрный хлеб» — ржаной; «селёдка» — солёная; «бульон» — куриный.", "«Паштет 30 г, 20 г багета» — две записи, веса не складываются. «Пол чайной ложки масла» остаётся половиной чайной ложки. «Одно капучино» — чашка, без вопроса про вес.", "Непонятный конец фразы не мешает записать понятное начало: бот запишет, что понял, и скажет, что не разобрал.", "В строке ввода диалога вместо второго микрофона — кнопка «Отправить». Микрофон один, внизу экрана."]}, {"version": "33.11", "date": "2026-11-18", "time": "21:14", "author": "Claude", "changes": ["Профиль и цели открываются листом: сверху видно приложение — нажал туда или на ручку — закрылось. Закрыл, не сохранив, — «Правки не сохранены · Вернуть».", "Замеры тела: широкие бёдра плавно переходят в ноги — без «ушей». В «Новом замере» ручка сверху вместо «Закрыть», «Удалить» — красная.", "Вход, профиль и цели: «Отмена» вместо «Отменить»; размеры текста — по общим правилам Happy."]}, {"version": "33.10", "date": "2026-11-18", "time": "18:57", "author": "Claude", "changes": ["Меры американского справочника USDA — по-русски и в наших единицах: «банка (298 г)» вместо «can (10.5 oz)», «85 г» вместо «3 oz», «столовая ложка» вместо «tbsp».", "Американская чашка подписана «чашка США (237 мл)»: это не наша чашка 200 мл и не стакан 250 мл. Граммы каждой меры — прежние, из USDA.", "Профиль → «Единицы измерения»: новая строка «Еда» — граммы и миллилитры или унции. Одна на аккаунт: поменял в Day, Meal или Sport — поменялось во всех трёх. Унции меняют подписи мер USDA; записанные граммы не меняются.", "Подписи видны в карточке продукта, «Подобрано», ответе «Что съел», дневнике, счётчиках и боте записи еды.", "Фрукты, ягоды и овощи называются «свежий», а не «сырой»: «Мандарин, свежий», «Огурец, свежий», «Клубника, свежая». Картофель, батат и другие клубни — «сырой», как говорят по-русски; мясо, рыба, крупы и бобы — как было. Калории и состав не менялись. «Свежий» и «сырой» бот и поиск понимают одинаково: «свежая клубника» и «сырая клубника» — одна и та же клубника.", "«Помидоры» без бота с включённым американским справочником снова записываются как томаты из основного списка, а не вопросом про жёлтые, зелёные и оранжевые помидоры."]},
 {"version": "33.9.2", "date": "2026-11-18", "time": "12:42", "author": "Claude", "changes": ["Без бота записи еды, с включённым американским справочником, «суп с лапшой» находился как консервированный концентрат «1 can (10.5 oz)». Теперь и в обычном поиске основная база первая: «суп с лапшой» — суп с лапшой из основной базы, тарелка 300 г; американский справочник — когда в основной базе такого нет."]},
 {"version": "33.9.1", "date": "2026-11-18", "time": "11:20", "author": "Claude", "changes": ["Продиктовал сразу после открытия, пока основная база ещё загружалась, — «Подобрано» предлагало только американские консервы («суп лапша» → концентрат). Теперь, когда база загрузится, варианты обновляются сами: «суп лапша одна тарелка» становится супом с лапшой, 300 г. Пока база грузится, под вопросом написано, что варианты обновятся."]},
 {"version": "33.9", "date": "2026-11-18", "time": "01:50", "author": "Claude", "changes": ["Бот записи еды (бета, выключен) понимает бытовую речь: «ну, короче», «хлебушек», «курятина», «полбанана», «тысяча двести грамм», «вернее 150», «180–200 г».", "Бот меньше спрашивает: «немного», «на глаз», «щедро» и продукт без веса записывает сразу со знаком «≈», под записью — «Меньше» и «Больше».", "Своя мера — первой: своя тарелка, кружка или порция продукта главнее общей.", "Меры: стакан 250 мл, чашка 200, кружка 300, пиала 250, половник 125; пучок зелени 50 г; бокал вина 150 мл, рюмка 50 мл. Названный объём («пол-литровая кружка») главнее.", "Японские порции — для японских блюд, корейские — для корейских: пиала мисо-супа 200 г, удон 200 г, миска корейского риса 210 г, рамён 500 мл, кимчи 40 г. Просто «кимчи» — из пекинской капусты; «бутерброд с сыром» — 50 г хлеба и 25 г сыра.", "Блюда «А с Б» нет в базе («гречка с маслом», «творог с изюмом») — бот предлагает записать по отдельности и запоминает твой ответ. Количество не названо — берётся твоя привычная порция этого продукта. Общее слово («рис», «масло», «вино») — то, что ты записывал последним, иначе привычный вариант.", "Штучные блюда: сырник и блин 50 г, пирожок 75 г, котлета 80 г, голубец 150 г. «N штук» — только у настоящей штуки: «10 пельменей» больше не превращаются в 10 тарелок супа.", "Сырое или готовое: сказал «съел курицу» — варёная, рыба — жареная, котлета — жареная; просто «курица 200 г» — сырая. Называл раньше способ — берётся тот же.", "В дневник идёт только съеденное тобой: «положила детям», рецепт, «котлет получилось 20 штук», «не считай» — не записываются. «Не доел, половину оставил» — записывается половина.", "Блюдо в соусе и с добавкой: «две котлеты в сливочном соусе», «борщ со сметаной», «блины со сметаной» — бот предлагает записать блюдо и соус или сметану по отдельности.", "Буханка хлеба 600 г, «полбуханки» — 300 г; ломоть и горбушка — как ломтик; ломоть арбуза 250 г. «Полгруши», «полтарелки» — половина меры.", "«Перепиши» больше не теряет прежнюю запись; «сколько калорий в 100 г риса?» отвечает справкой о рисе, а не итогом дня.", "Слова и веса мер лежат в одном словаре; в «Правилах бота» — три новых раздела обычным языком."]},{"version": "33.8", "date": "2026-11-17", "time": "19:00", "author": "Claude", "changes": ["Бот записи еды (бета, выключен): новые правила, в какой приём пишется еда. Еда ближе 1,5 часа к записи — в тот же приём; немного еды (до 150 ккал или только напиток) после приёма — перекус; иначе следующий приём по порядку: завтрак → обед → ужин.", "Поздний ужин больше не уходит в перекус, поздний обед — в ужин. Первая еда дня до 13:00 — завтрак.", "«Вчера груша 200 г» без времени — бот спрашивает кнопками, в какой приём. Ночью «на ужин…» — вчерашний ужин.", "В «Для разработчика» — «Правила бота»: обычным языком, куда бот записывает еду."]},{"version": "33.7", "date": "2026-11-17", "time": "14:50", "author": "Claude", "changes": ["16:21 · Продукты USDA (США, 7 793) по-русски: «белый рис», «клубника свежая», «сгущёнка» находят их; английское название — в карточке, строкой «Оригинал». Обновил Claude.", "Бот записи еды (бета, выключен): штуку берёт из основной базы, а случайное слово в середине названия справочника («омега-3» в арахисовой пасте) не записывает."]}, {"version": "33.6", "date": "2026-11-17", "time": "03:16", "author": "Claude", "changes": ["Бот записи еды · бета 1 — пока выключен. Включается в настройках, в разделе «Для разработчика» (долгое нажатие на строку версии).", "С ботом диалог «Что съел» сам записывает понятное, а о неясном спрашивает; правится словами: «нет, 180 г», «нет, на завтрак», «отмени».", "Пока бот выключен, Meal работает как раньше."]},{"version": "33.5", "date": "2026-11-17", "time": "02:34", "author": "Claude", "changes": ["Углеводы у продуктов USDA теперь идут в дневник: углеводы по разности минус клетчатка, как у других каталогов, со значком ≈. Например, варёный белый рис — ≈ 27,8 г на 100 г вместо прочерка. Где клетчатка не указана — по-прежнему прочерк.", "Уже сделанные записи не пересчитываются."]},{"version": "33.4", "date": "2026-11-17", "time": "02:10", "author": "Claude", "changes": ["Новый каталог KFCT · Южная Корея: 3 366 продуктов официальной корейской таблицы состава 10.4 — кимчи, рис, водоросли, рыба, соусы. Названия по-русски, по-английски и по-корейски; искать можно на любом из трёх языков.", "Каталог есть в «Сборниках» и включается в настройках каталогов, как остальные.", "В корейской таблице «углеводы всего» — вместе с клетчаткой. В дневник, как у других каталогов, идут углеводы без клетчатки, а в карточке — обе строки: «Углеводы всего» и «из них клетчатка»."]},{"version": "33.3", "date": "2026-11-17", "time": "00:38", "author": "Claude", "changes": ["Новый каталог «Сладкие заготовки»: варенья, джемы, компоты, фрукты в сиропе и цукаты. Семь новых карточек по справочникам — кизиловое и малиновое варенье, джем и варенье из чёрной смородины, вишнёвое варенье, компот из крыжовника и смородины, яблочный компот с плодами — и 20 готовых продуктов BLS и USDA, без дублей; у продуктов USDA — русские названия.", "Каталог есть в «Сборниках» — с обложкой и списком позиций, — включается и выключается в настройках каталогов, как остальные.", "Джемы и соки MEXT — по-русски: «Клубничный джем», «Яблочный джем», «Джем из голубики», «Лимонный сок» вместо «Клубника, джем» и «Лимон, сок». Теперь их находит обычный запрос; состав прежний."]},{"version": "33.2", "date": "2026-11-16", "time": "17:40", "author": "Claude", "changes": ["Замеры тела: новый силуэт — ноги и стопы естественнее, голова крупнее, углы сглажены. Силуэт учитывает рост из профиля: при тех же замерах невысокий человек выглядит плотнее, высокий — стройнее."]}, {"version": "33.1", "date": "2026-11-16", "time": "12:10", "author": "Claude", "changes": ["Японский каталог MEXT — полная таблица: 2538 продуктов вместо 520, среди них джемы, засахаренные каштаны, японские сладости, рыба и мясо. Прежние продукты и записи дневника не изменились.", "Полная таблица не замедлила Meal: список продуктов собирается быстрее прежнего, памяти нужно почти столько же, сколько с выборкой 520.", "У морковной ботвы и кожицы моркови больше нет мер целой моркови."]},
 {"version": "33", "date": "2026-11-16", "time": "03:48", "author": "Claude", "changes": ["Без входа приложение открывается первым экраном: стеклянный смайлик, дуга докручивается до улыбки снизу, потом появляются кнопки «Продолжить с почтой», «Уже есть аккаунт? Войти» и «Познакомиться с Meal». Кнопки Apple и Google пока не нажимаются — этот вход ещё не подключён.", "Регистрация: почта, пароль и повтор пароля, пароль можно показать. Затем — ожидание письма: «Отправить повторно» и «Изменить почту». Подтвердили почту и вернулись — приложение открывается само, без анкеты.", "Без входа приложение можно смотреть. Попробовали записать — лист «Войдите в аккаунт»; после входа приложение возвращается туда же. Неверный пароль — понятная ошибка.", "Настройки без большого заголовка: вверху фото и имя, карточка «Настроить профиль» и «Настроить цели», ниже «Связка с» двумя свитчами. Остальные настройки — как были. В самом низу — «Выйти» и строка синхронизации.", "Профиль один на Day, Meal и Sport: фото, имя и фамилия, почта с отметкой «Подтверждена», дата рождения, рост, пол, вес с датой замера; единицы веса и роста — отдельно. Новый вес — новый замер с датой, прежние не меняются.", "Цели Meal: вес сейчас и желаемый вес — полем или линейкой; снижение, поддержание, рекомпозиция или набор; калории и БЖУ — «Рассчитать» (по активности, с поправкой) или «Установить вручную», доли БЖУ всегда 100 %. Клетчатка — как раньше. «Цели на день» из настроек переехали сюда."]},
 {"version": "32.3", "date": "2026-11-16", "time": "00:42", "author": "Claude", "changes": ["Силуэт на экране замеров точнее: таз и бёдра — одна плавная линия, между ног ничего не торчит; плечи и грудь меняют фигуру; при сравнении «Было» и «Сейчас» руки не съезжают — нет ложного розового; у полного человека плечи без «подплечников». Формат замеров не менялся.", "Кольцо энергии: при переключении на «потрачено» больше не всплывает подсказка «Потраченное придёт из Happy Sport»."]},
 {"version": "32.2", "date": "2026-11-15", "time": "13:59", "author": "Claude", "changes": ["Экран замеров тела: вместо трёх кнопок одна — «Поделиться». Нажал — рядом с кнопкой маленькое меню: «Печать замеров» и «Выгрузить CSV». Замер исправляют карандашом у его даты.", "Новый силуэт на экране замеров: естественная фигура. Где «Было» и «Сейчас» совпадают — голубой, что прибавилось — розовый край, что ушло — бирюзовый. При смене периода и масштаба силуэт плавно перетекает.", "Журнал: нет лишнего заголовка «Журнал» под переключателем.", "Поправили время нажатия на счётчике еды в Happy Day или Happy Sport — порция переезжает в нужный приём пищи."]},
 {"version": "32.1", "date": "2026-11-15", "time": "01:56", "author": "Claude", "changes": ["Вход снова у каждого приложения свой: вход и выход здесь не трогают Happy Day, Happy Meal и Happy Sport. Аккаунт и записи общие: войди в каждое приложение под тем же аккаунтом — и обмен работает, как раньше.", "После этого обновления нужно один раз заново войти. Записи никуда не делись: они в аккаунте и придут сами."]}, {"version": "32", "date": "2026-11-15", "time": "00:45", "author": "Claude", "changes": ["Записи только после входа в аккаунт Happy. Без входа Meal предлагает войти; после входа запись работает и без сети и сама уходит в облако.", "Вход общий с Happy Day и Happy Sport: вошёл в одном приложении — вошёл во всех, вышел — вышел из всех.", "Дневник, свои продукты, счётчики и добавки хранятся и обмениваются через общий модуль Happy: правка с другого устройства или вкладки появляется сама; при правке одной записи с двух устройств остаётся поздняя, удалённое не возвращается.", "Счётчик еды, которому включён показ в Day или Sport, появляется там сам. Число на счётчике одно во всех трёх приложениях: «+» и «−» работают в любом, «−» убирает последнюю порцию, где бы её ни нажали.", "Порция со счётчика видна в дневнике Meal, где бы её ни нажали; поправить и убрать её можно здесь.", "Счётчик, убранный со страницы Day, в Meal остаётся: у него выключается показ в Day. Включить обратно — в настройках счётчика.", "Каталог добавок и их состав остаются в Meal: соседним приложениям уходит только счётчик и итог дня.", "Meal снова видит тренировки из Happy Sport в кольце «потрачено».", "Замеры тела — тот же экран, что в Sport и Day: вкладка «Замеры тела» в журнале.", "Свитчи связи с Day и Sport стали общими: переключил в одном приложении — в другом свитч уже переключён.", "Если записи сделаны более новой версией приложения, прежняя версия их не меняет и предлагает открыть последнюю.", "«Выгрузить дневник» осталась в разделе для разработчика. Загрузки дневника из файла больше нет: дневник хранится в аккаунте и приходит на устройство сам.", "Meal 32 открывается с пустым дневником: записи прежних версий не переносятся и остаются в Meal 31."]}, {"version": "31.1", "date": "2026-11-13", "time": "12:09", "author": "Claude", "changes": ["В поиске под названием — калории на 100 г и каталог, как у других продуктов: «344 ккал / 100 г · Узбекская кухня».", "Меры блюд узбекской кухни — «порция», «большая порция», «шт», «упаковка» вместо «пример» и «справочная масса»; у нишалды и навата — граммы.", "Под мерами — одна строка о том, что считается: «Без кожуры», «Съедобная часть».", "Названия без перестраховки: без «справочный ориентир», «расчётная оценка», «— рецепт», «по MEXT»; «Сузьма 6%» — без марки.", "Длинная мера больше не ломает продукт в приёме: название видно всегда.", "Карточки каталогов (ⓘ) — коротко: что в блюде, выход и источник.", "Картинки «Сборников» берутся из копии на телефоне и появляются сразу и ровно.", "Десерты 1.2: 27 типовых названий без марок, козинак пересчитан, у чизкейка Нью-Йорк — витамины B1, ниацин и фолиевая кислота."]}, {"version": "31", "date": "2026-11-13", "time": "11:04", "author": "Claude", "changes": ["Meal стал быстрее: нажатие, которое ничего не меняет, больше не запускает сохранение и синхронизацию.", "Состав каждого продукта хранится на устройстве один раз: дневник занимает втрое меньше места и сохраняется быстрее.", "Дневник и сводка для Happy Day и Happy Sport уходят в облако, только когда в них что-то изменилось.", "Из сводки убраны дневные итоги по всем витаминам и минералам: Day и Sport их не показывают. В Meal микроэлементы считаются как раньше."]}, {"version": "30", "date": "2026-11-12", "time": "23:29", "author": "Claude", "changes": ["Связь с Happy Day и Happy Sport — свитчами сразу под аккаунтом: название открывает приложение, свитч включает и выключает связь. Раздел «Связанные приложения» внизу настроек, текст «Один аккаунт и одно имя…» и подпись «Оформление» убраны.", "Свитч — связь пары в обе стороны: выключил в любом из двух приложений — связи нет, в обоих одно состояние. Пока связь с Sport выключена, его тренировки с этого момента не идут в «потрачено»; что было раньше, остаётся; включил обратно — видно всё, и пропущенное. Day и Sport, пока связь выключена, не берут еду из Meal. В окне счётчика свитч синхронизации с отключённым приложением неактивен.", "Дневник: дуга «съедено» в кольце — плавный цвет, без черточек на iPhone. Под кольцом нет пояснения «Калории и БЖУ: сумма известных значений…», нет строки «Голодание прервано» и отдельного блока «Добавки». Добавка записывается в приём пищи, как любая еда, и считается продуктом («2 продукта»); из поиска на главном — в приём по времени.", "Журнал: нет «Добавки за период» и подписей «нет данных в N записях добавок». «Избранное» — только то, что ты отметил звёздочкой. Свои вещества — в рамке «Мои микроэлементы» внизу, их тоже можно отметить звёздочкой. У «Омега-3» убран «Подытог двух кислот».", "Счётчики: под ними не пишется «Счётчики синхронизированы» — только если что-то не так. Окно счётчика закрывается черточкой сверху: нажать или потянуть вниз. В окне есть корзина. Количество с запятой: «0,5 стакана». Цвет окна прежний.", "Каталоги: разделы «… · Cronometer» убраны из настроек, в прошлых днях записи на месте. Отключённая библиотека не ищется нигде, и в «Новом счётчике» тоже; счётчик продукта из неё тусклый, нажатие — «Библиотека с данным продуктом отключена», набранное число остаётся.", "Не купленный набор «БАДы» — как отключённый: его нет в поиске и в настройках каталогов. Купил — сразу подключён.", "Добавки: в магазине «Редактировать» видна, но неактивна — подсказка «Редактирование доступно после добавления в библиотеку». Шаблоны без брендов: «Типичный состав», без ссылок на этикетки производителей.", "Окно добавки: вместо «Приём пищи · По форме» — «Сбрасывает окно голодания?»: Да · Нет · Если больше 4 ккал (по умолчанию, для любой формы). «Отмена» закрывает без вопроса. «+ Добавить свою меру» больше не прыгает вверх. Подсказки «Новое вещество» — в цветах приложения."]},
 {"version": "29.1", "date": "2026-11-12", "time": "09:07", "author": "Claude", "changes": ["Шаблон из каталога БАДов, пока каталог не куплен, больше не тупик: в карточке написано, что БАДы не подключены к библиотеке, есть «Купить · 2 €», как в магазине, и «В магазин» — на страницу каталога. После покупки прямо в карточке сразу открывается «Добавить в дневник». В поиске такие строки подписаны «Каталог БАДов · не подключён»."]},
 {"version": "29", "date": "2026-11-12", "time": "02:51", "author": "Claude", "changes": ["БАДы в «Сборниках»: каталог шаблонов по этикеткам — омега-3, магний, протеины, коллаген, витамины. Тестовая покупка открывает настройку состава под свою упаковку.", "«Мои добавки»: свои варианты и записанные приёмы хранятся в аккаунте и видны на всех устройствах.", "Приём БАДа записывается в завтрак, обед или другой раздел; калории и БЖУ добавок входят в итоги дня, журнал, отчёт и Happy Day.", "Приём пищи открывает запись, в которой больше 4 ккал: кофе с молоком, чай с сахаром, компот, протеин, коллаген. Вода, чёрный кофе и чай без сахара — никогда. Капсулы и таблетки приём не открывают.", "Новая отметка «Голодание прервано» — время первой записи с калориями, в том числе рыбьего жира в капсулах.", "Счётчик можно сделать и для добавки: в «Новом счётчике» найди её среди своих добавок, выбери капсулы, таблетки или мерную ложку и подключи Happy Day и Happy Sport. Нажатие в любом из них записывает приём, а вес капсулы, если он неизвестен, нигде не показывается.", "Каталог БАДов можно скачать на телефон, как остальные каталоги. В журнале омега-3 показана вместе с ЭПК и ДГК. «Выгрузить дневник» сохраняет и добавки."]}, {"version": "28", "date": "2026-11-11", "time": "23:07", "author": "Claude", "changes": ["«Библиотека» стала «Сборниками»: магазин каталогов, «Мои рецепты» и «Мои продукты», общий поиск по каталогам и своим записям.", "В магазине — карточки каталогов с обложками. В узбекской кухне и десертах виден список блюд с калориями, белками, жирами и углеводами.", "Покупка пока тестовая: без оплаты, отметка «Куплено» хранится на этом телефоне.", "Настройки → Каталоги: карточки листаются вбок, у каждой — переключатель «Подключено / Отключено».", "Каталог можно скачать на телефон: Meal откроется и найдёт продукты без интернета.", "Знак «≥» у белков, жиров и углеводов убран."]}, {"version": "27.4", "date": "2026-11-11", "time": "23:07", "author": "Claude", "changes": ["Время продукта в «Корректировке» можно набрать сразу поверх прежнего — стирать его больше не нужно. Так же в окне времени всего приёма.", "Время приёма пищи — время первого продукта: поставил продукту время раньше — время всего приёма сдвигается на него, и Happy Day видит то же время. Напитки приём не открывают."]},{"version": "27.3", "date": "2026-11-11", "time": "17:43", "author": "Claude", "changes": ["Порции со счётчиков, нажатые в Happy Sport и Happy Day, сразу видны там в «съедено» — открывать Meal для этого больше не нужно.", "Meal считает день как раньше и не учитывает эти порции дважды."]},{"version": "27.2", "date": "2026-11-11", "time": "16:18", "author": "Claude", "changes": ["В кольце энергии видно время тренировок из Happy Sport: оно приходит само — с этого устройства и из аккаунта.", "Съеденное, клетчатка и «Цели на день» теперь доходят до кольца в Happy Sport и Happy Day.", "Общий расход за день Sport пока не считает — в «потрачено» и «балансе» на его месте прочерк."]},{"version": "27.1", "date": "2026-11-10", "time": "11:30", "author": "Claude", "changes": ["Разделы, перенесённые из Cronometer («Morning Starter · Cronometer» и другие), видны только в прошлых днях, где в них есть записи, и не появляются в новых днях.", "Под кнопкой «Выйти» — одна строка состояния: «Подождите, идёт синхронизация…» → «Синхронизировано»; без сети — «Нет связи · записи сохранены на устройстве». «Выйти» ждёт, пока журнал уйдёт в облако (до 15 секунд).", "«Не удалось сохранить журнал» больше не всплывает при обычной работе: запись на устройство повторяется молча; сообщение — только если не получается дольше 30 секунд.", "Текст под аккаунтом короче: один аккаунт на три приложения, сохрани пароль."]},{"version": "27", "date": "2026-11-10", "time": "00:50", "author": "Claude", "changes": ["Поиск десертов по привычным названиям: «берлинер», «панакота», «крем-брюле», «шварцвальд», «захер», «грильяж», «булочка с корицей» и другие — 44 продукта базы BLS находятся по русским словам. Новых карточек нет, состав прежний.", "15 записей USDA (чизкейк, брауни, круассаны, пончики, карамель) получили русские названия в самой базе — они остаются и при выключенной коллекции «Десерты»."]}, {"version": "26.1", "date": "2026-11-09", "time": "19:37", "author": "Claude", "changes": ["Служебное убрано с глаз: резервная копия («Выгрузить / Загрузить дневник») и «Обновить связь» — в разделе «Для разработчика» (долгое нажатие на строку версии). В «Данных» остались отчёты.", "Дневник, вход, базы и десерты — как в 26."]}, {"version": "26", "label": "Happy Meal · Update 26", "date": "2026-11-09", "time": "16:56", "author": "Claude", "changes": ["Настройки собраны по единой структуре Happy: Аккаунт (вход и строка состояния) → Приложение (оформление, цели, разделы, счётчики, мои продукты, пищевые базы) → Данные (отчёты, резервная копия) → Связанные приложения → версия. Служебные блоки прототипа — в скрытом разделе «Для разработчика»: открывается долгим нажатием на строку версии внизу.", "Кнопки резервной копии названы одинаково с Day и Sport: «Выгрузить дневник», «Загрузить дневник», «Вернуть дневник до загрузки».", "Кнопки «Happy Day» и «Happy Sport» сами узнают текущие выпуски соседних приложений (из общей карты выпусков) — больше не устаревают после их обновлений.", "Дневник, вход, счётчики, библиотеки — как в Update 25."]}, {"version": "25", "label": "Happy Meal · Update 25", "date": "2026-11-09", "time": "15:43", "author": "Claude", "changes": ["Подключена библиотека десертов 1.0 (ChatGPT, 09.11.2026): 97 записей. 30 карточек — этикетки производителей и расчётные модели — в новой базе «Десерты» (Настройки → Пищевые базы, переключатель). 67 десертов из BLS, USDA, кавказской и узбекской кухни остались в своих базах без второй карточки: у них появилось слово «десерт» в поиске, у 15 записей USDA — русские названия («Чизкейк, промышленный» вместо Cake, cheesecake…).", "Неизвестные нутриенты — не ноль. «Менее 0,5 г» на этикетке показывается как граница «< 0,5 г». Углеводы этикеток США (включая клетчатку) — отдельной строкой, как у USDA.", "Порции — только из данных источника: изделие или упаковочная порция («порция ≈ 10 шт»); где размера нет — запись по граммам. Семь черновых позиций набора в приложение не входят.", "Ложное «Вход изменился во время операции» / «Аккаунт или ключ изменились» больше не появляется, когда во время нажатия обновляется токен того же аккаунта: вход теперь узнаётся по аккаунту и ключу, а не по токену; токен обновляется один раз за операцию, свежий вход из соседнего окна принимается без паузы. Смена аккаунта или ключа по-прежнему останавливает запись.", "В списке счётчиков у строки осталась только порция — подписи «· Day · Sport» убраны (связь с приложениями видна в редактировании счётчика).", "Кнопки «Happy Day» и «Happy Sport» в настройках открывают соседнее приложение в новом окне — Meal остаётся на месте.", "Дневник, вход, счётчики — как в Update 24."]}, {"version": "24", "label": "Happy Meal · Update 24", "date": "2026-11-09", "time": "12:40", "author": "Claude", "changes": ["Вход в Meal хранится отдельно от Day: обновление входа в соседнем приложении больше не выбрасывает из Meal и не перезагружает страницу. При первом открытии прежний вход подхватывается сам.", "Если один общий счётчик показывался двумя строками (как «Вода питьевая» 09.11), строки сливаются в одну; порции не теряются.", "Кнопки «Happy Day» и «Happy Sport» в настройках открывают текущие выпуски.", "Сообщения об ошибках называют причину (вход обновился / нет места / журнал не прочитан) и больше не просят выгружать JSON; заглушки PRO / GOLD убраны из шапки настроек.", "История обновлений рисуется общим модулем Happy: у каждой записи, начиная с этой, автор и время публикации; внизу настроек — дата, время и автор обновления.", "Модуль общих счётчиков — тот же, что в Day и Sport: после записи в облако результат перечитывается и сверяется."]}, {"version": "23", "label": "Happy Meal · Update 23", "date": "2026-11-07", "changes": ["Согласованный выпуск Happy Meal. Полный журнал, свои продукты и рецепты автоматически синхронизируются после входа в аккаунт.", "Состояние синхронизации отображается под кнопками профиля в настройках.", "Пищевые базы подключены как самостоятельные библиотеки и обновляются независимо от приложения при следующем открытии.", "Один дневник доступен в браузерах и установленном на экран «Домой» приложении после входа в тот же аккаунт."]},{"version": "22.11-usda-test.15", "date": "2026-11-07", "changes": ["Пищевые базы подключены как самостоятельные библиотеки: BLS, USDA, MEXT, Кавказская и Узбекская кухня. Новые совместимые версии библиотек загружаются при открытии приложения.", "Подключена самостоятельная узбекская библиотека 1.7.0: 53 карточки. Уже записанный состав еды сохраняется.", "Исправлен первый запуск. Статус синхронизации остаётся под кнопками профиля."]},{"version": "22.11-usda-test.14.1", "date": "2026-11-07", "changes": ["Исправлен первый запуск: состояние входа готово до чтения журнала, поэтому приложение не принимает свою инициализацию за смену аккаунта.", "Сохранён компактный статус синхронизации под кнопками профиля. Отдельный тест в Sites для проверки Safari и Brave."]},{version:"22.11-usda-test.14",date:"2026-11-07",changes:["Статус синхронизации расположен под кнопками профиля в настройках.","После новой правки статус сразу показывает синхронизацию; подтверждение появляется только после обмена с облаком."]},{"version": "22.11-usda-test.13", "date": "2026-11-06", "changes": ["Локальная подготовка выпуска: усилена привязка операций аккаунта и данных к владельцу; сводки Meal отправляются последовательно в одном открытом приложении.", "Общий профиль, запись с нескольких устройств и неопределённый результат сетевой записи этим исправлением не решены. Встроенные Day, Sport и замеры не обновлялись."]},{"version": "22.11-usda-test.12", "date": "2026-11-02", "changes": ["Тема сразу видна при выборе: меняются фон приложения, центральная кнопка и само окно оформления.", "«Применить» сохраняет выбор. Закрытие, «Отмена», Escape и нажатие снаружи возвращают прежний вид без сохранения."]},{"version": "22.11-usda-test.11", "date": "2026-11-02", "changes": ["Выбранная тема теперь меняет фактически видимый фон Meal, а не только фон под ним. Исходный бордовый вид по умолчанию сохранён."]},{"version": "22.11-usda-test.10", "date": "2026-11-02", "changes": ["Под аккаунтом появился выбор оформления: 10 общих тем из Color Studio 12.5.", "Исходный вид остаётся по умолчанию. Тема меняется только после «Применить»; можно вернуться к исходному оформлению.", "Выбор сохраняется отдельно в этом приложении. Дневник, аккаунт и прежние настройки не меняются."]},{version:"22.11-usda-test.9",date:"2026-11-02",changes:["Все пищевые базы включены по умолчанию. В этой тестовой версии прежние выключенные базы включаются один раз, чтобы продукты было проще найти.","После этого свой выбор баз можно менять: последующие выключения сохраняются, в том числе при синхронизации. Дневник и другие настройки не сбрасываются."]},{version:"22.11-usda-test.8",date:"2026-11-02",changes:["В общую библиотеку добавлены шурпа с бараниной и говядиной, манты с бараниной и духовая самса — адаптированные расчётные рецепты BLS + USDA.","Манты: 60 г за штуку; шурпа: 500 г по рецептуре. Для самсы треугольник и квадратный конверт — редактируемый целевой вес 120 г, не универсальный размер.","Углеводы недостающих ингредиентов оценены по документированному методу USDA/FAO; исходные базы и калорийность не пересчитаны. Выход отделён от потерь нутриентов, которые ещё не откалиброваны."]},{version:"22.11-usda-test.7",date:"2026-11-02",changes:["Плов переименован в «Плов узбекский с бараниной» и «…с говядиной»; прежние названия остались синонимами. Это общие продукты Happy Meal; отдельный блок из личной Библиотеки убран.","Пустой поиск объясняет, какие базы выключены, и ведёт к их настройкам. Выключенные продукты не удаляются. Ошибку загрузки можно повторить без очистки данных.","Новая утверждённая иконка из Icon Studio: Дэн с мягким мороженым на сине-бирюзовом фоне."]},{version:"22.11-usda-test.6",date:"2026-11-02",changes:["Узбекская кухня в библиотеке: два адаптированных рецепта плова с зирой на основе BLS + USDA, источник каждого ингредиента и выход 350 г.","Для плова: маленькая пиала 300 г, большая 500 г — измеренные пользовательские меры, доступные для изменения. Потери нутриентов ещё не откалиброваны; неизвестные значения не заменяются нулями."]},{version:"22.11-usda-test.4",date:"2026-11-02",changes:["Короткая единая подпись «Среднее значение» для недели, месяца и выбранного многодневного периода; расчёты не изменены."]},{version:"22.11-usda-test.3",date:"2026-11-02",changes:["Исправлены подписи источников и привязка сохранённых продуктов BLS к библиотеке без изменения замороженного состава.","Исторические разделы поддерживают дату окончания видимости: прошлые записи остаются доступны.","Примечание к условной оценке напитка остаётся у записи, а не переименовывает продукт библиотеки."]},{version:"22.11-usda-test.1",date:"2026-11-01",changes:["Отдельный тест официальной USDA SR Legacy: 7 793 продукта, выпуск апреля 2018 года.","Названия, коды FDC, исходный состав и справочные массы порций. Русский перевод пока для специй и части зелени; остальные названия английские.","История питания не переназначается. Неизвестные и отличающиеся определения нутриентов не заменяются нулями."]},{version:"22.11-test.18",date:"2026-10-31",changes:["Новая иконка Happy Meal: Дэн в кепке с ложкой на зелёно-бирюзовом фоне."]},{version:"22.11-test.17",date:"2026-10-31",changes:["Полный журнал, свои продукты и рецепты синхронизируются в зашифрованном виде после входа.","Записи объединяются по ID; удаления, офлайн-правки и повторный импорт защищены ревизиями.","В настройках показан отдельный статус полного журнала. Старые сборки без этой функции требуют обновления."]},{version:"22.11-test.16",date:"2026-10-31",changes:["Пустой журнал больше не показывает демонстрационные данные: 0 ккал и понятное пустое состояние."]},{version:"22.11-test.15",date:"2026-10-31",changes:["Добавлена иконка установки для главного адреса и стандартных путей Apple touch icon."]},{version:"22.11-test.14",date:"2026-10-31",changes:["Возвращена карусель пищевых баз с открытой карточкой; свитч справа от названия.","Последнюю базу выключить нельзя. Японский недоступен при выключенной MEXT; языки поиска пояснены отдельно."]},{"version": "22.11-test.13", "date": "2026-10-31", "changes": ["Добавлены и уточнены штучные меры фруктов, овощей, ягод, орехов и яиц.", "Киви и другие продукты MEXT получили размеры; у яичницы — маленькое, среднее и большое яйцо.", "Вес порций отмечен как приблизительный; свои меры и записанные граммы сохраняются."]}, {"version": "22.11-test.12", "date": "2026-10-31", "changes": ["В конце настроек добавлена «История обновлений».", "Изменения собраны по версиям и датам, новые — сверху."]}, {"version": "22.11-test.11", "date": "2026-10-31", "changes": ["Пищевые базы включаются независимыми свитчами; одна база всегда остаётся включённой.", "Виджет согласован с Happy Sport: пустые полосы БЖУ и клетчатки видны без заданных целей.", "Отчёты и выгрузки собраны в конце настроек."]}, {"version": "22.11-test.10", "date": "2026-10-30", "changes": ["В редакторе счётчика — пилюля количества с минусом и плюсом, карусель мер и своя порция.", "Свитчи связи с Day и Sport выровнены по центру строк."]}];
document.getElementById('releaseHistory').innerHTML=(typeof HappyReleaseNotes!=='undefined')?HappyReleaseNotes.render(mealReleases,{heading:'h2'}).replaceAll('class="happy-card happy-release"','class="card release-card happy-release"'):mealReleases.map(r=>'<article class="card release-card"><h2>'+escH(r.label||('Версия '+r.version))+'</h2><time datetime="'+r.date+'">'+r.date.split('-').reverse().join('.')+'</time><ul>'+r.changes.map(t=>'<li>'+escH(t)+'</li>').join('')+'</ul></article>').join('');
document.getElementById('openReleaseHistory').addEventListener('click',()=>go('updates'));
document.querySelector('[data-screen="updates"] [data-grip]').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();closeSheet();}});
